class _Platform extends PlatformPlugin {
  _Platform(this._host);
  final _Host _host;

  @override
  Future<RunnerSuite> load(String path, SuitePlatform platform, SuiteConfiguration suiteConfig,
      Object message) async {
    final _Suite? suite = _host.suites[path];
    if (suite == null) throw StateError('dartq: $path is not part of the grouped run');
    final _Tester tester;
    try {
      tester = await _host.acquire(suite);
    } catch (_) {
      _host.dirty.add(suite.id);
      _host.accounted(suite.id);
      rethrow;
    }
    WebSocket socket;
    try {
      socket = await tester.run(suite);
    } catch (_) {
      _host.dirty.add(suite.id);
      _host.accounted(suite.id);
      tester.retire = true;
      await tester.settle();
      rethrow;
    }
    final StreamChannel<Object?> channel = StreamChannel<Object?>.withGuarantees(
      socket.map<Object?>((Object? data) => jsonDecode(data! as String)),
      _Sink(socket, tester),
    );
    return deserializeSuite(path, platform, suiteConfig, const PluginEnvironment(), channel, message)
        .suite;
  }
}

Future<void> main(List<String> args) async {
  final _Host host =
      _Host(jsonDecode(File(args.single).readAsStringSync()) as Map<String, Object?>);
  final List<Object?> suites = host.config['suites']! as List<Object?>;
  for (int id = 0; id < suites.length; id++) {
    final List<Object?> row = suites[id]! as List<Object?>;
    final _Suite suite =
        _Suite(id, row[0]! as String, row[1]! as int, row[2]! as int, row[3]! as bool);
    host.suites[suite.path] = suite;
    host.byId.add(suite);
  }
  host.server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
  host.server.listen(host.accept);
  registerPlatformPlugin(<Runtime>[Runtime.vm], () => _Platform(host));
  registerReporter(
      'json',
      ReporterDetails('A machine-readable format.', (config, engine, sink) {
        host.sink = sink;
        final JsonReporter reporter = JsonReporter.watch(engine, sink, isDebugRun: config.debug);
        engine.onSuiteStarted.listen((liveSuite) {
          final suite = liveSuite.suite;
          if (suite is LoadSuite) return;
          final _Suite? hosted = host.suites[suite.path];
          if (hosted == null) return;
          liveSuite.onClose.then((_) => host.closed(hosted.id));
        });
        return reporter;
      }));
  await executable.main((host.config['args']! as List<Object?>).cast<String>());
  final int code = exitCode;
  for (final _Tester tester in List<_Tester>.of(host.testers)) {
    await tester.stop();
  }
  await host.server.close(force: true);
  await stdout.flush();
  exit(code);
}
